{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Desipramine, a close structural analogue sharing the aryl-propylamine motif, has a mean absolute oral bioavailability of 38% in healthy volunteers after a 50 mg oral dose, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Imipramine, another closely related tricyclic propylamine antidepressant, shows approximately 40% absolute oral bioavailability in healthy subjects, supporting high F for this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Fentanyl, an N-phenyl tertiary amine opioid with some structural overlap, has an absolute oral bioavailability of 0.31 in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Amitriptyline, a related tricyclic antidepressant, shows high absolute oral bioavailability of 96.2% in humans, supporting high F for lipophilic basic amine drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "The aminotetralin N-0437 has low oral bioavailability, but this contradictory evidence is weakly transferable because the molecule contains a phenolic hydroxyl and thienyl substituent that confer a different first-pass metabolic liability than the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable experimental evidence from structurally related basic arylamine/propylamine drugs (desipramine, imipramine, fentanyl, amitriptyline, nortriptyline) shows absolute oral bioavailability above 20%, typically in the 30-60% range. The low-F rotigotine/N-0437 analogues are less transferable because of phenolic/thienyl substitution and extensive first-pass metabolism. Therefore the query is predicted to have high oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement is available for the query molecule.",
    "Morgan similarities are modest (~0.23-0.28), so structural transfer is indirect.",
    "The low-F aminotetralin evidence is from phenolic/thienyl analogues whose metabolic liability may not apply to the non-phenolic query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

